@chain data begin
  @transform :educ = ifelse.(in.(:EDUC,Ref([72,73])), "hs",       #&lt;- HS diploma, no college
                     ifelse.(90 .&lt;= :EDUC .&lt; 110, "two_yr",          #&lt;- associate's / 2-3 yrs college
